import itertools
import struct

ITEM = 4
ALIGN = 8

class LoadError(ValueError):
    pass

def prod(shape):
    p = 1
    for s in shape:
        p *= s
    return p

def lin(coords, shape):
    idx = 0
    for c, s in zip(coords, shape):
        idx = idx * s + c
    return idx

def write_tensor(data, offset, shape, base):
    for c in itertools.product(*[range(s) for s in shape]):
        struct.pack_into('<i', data, offset + lin(c, shape) * ITEM, base + lin(c, shape))

def read_value(data, offset, shape, coords):
    return struct.unpack_from('<i', data, offset + lin(coords, shape) * ITEM)[0]

def validate(records, file_size, required):
    names = {}
    for r in records:
        if r['name'] in names:
            raise LoadError('duplicate name')
        names[r['name']] = r
    for r in records:
        if 'alias_of' in r:
            if r['alias_of'] not in names:
                raise LoadError('missing alias root')
            root = names[r['alias_of']]
            while 'alias_of' in root:
                root = names[root['alias_of']]
            if tuple(r['shape']) != tuple(root['shape']) or tuple(r['order']) != tuple(root['order']):
                raise LoadError('alias representation differs')
            r['root'] = root['name']
            continue
        n = prod(r['shape']) * ITEM
        if r['offset'] % ALIGN != 0:
            raise LoadError('unaligned offset')
        if r['offset'] + n > file_size:
            raise LoadError('range outside file')
    spans = []
    for r in records:
        if 'alias_of' not in r:
            n = prod(r['shape']) * ITEM
            spans.append((r['offset'], r['offset'] + n, r['name']))
    spans.sort()
    for a, b in zip(spans, spans[1:]):
        if b[0] < a[1]:
            raise LoadError('overlapping payload ranges')
    for name in required:
        if name not in names:
            raise LoadError('missing required tensor')
    return names

def materialize(records, data, ignore_order=False):
    validate(records, len(data), set(r['name'] for r in records))
    out = {}
    for r in records:
        if 'alias_of' in r:
            continue
        order = tuple(range(len(r['shape']))) if ignore_order else tuple(r['order'])
        tshape = tuple(r['shape'][i] for i in order)
        buf = bytearray(prod(tshape) * ITEM)
        for tcoords in itertools.product(*[range(s) for s in tshape]):
            scoords = [0] * len(r['shape'])
            for k, ax in enumerate(order):
                scoords[ax] = tcoords[k]
            v = read_value(data, r['offset'], r['shape'], tuple(scoords))
            struct.pack_into('<i', buf, lin(tcoords, tshape) * ITEM, v)
        out[r['name']] = bytes(buf)
    for r in records:
        if 'alias_of' in r:
            out[r['name']] = out[r['root']]
    return out

def reference(records, data, name):
    names = validate(records, len(data), set(r['name'] for r in records))
    r = names[name]
    while 'alias_of' in r:
        r = names[r['alias_of']]
    order = tuple(r['order'])
    tshape = tuple(r['shape'][i] for i in order)
    buf = bytearray(prod(tshape) * ITEM)
    for scoords in itertools.product(*[range(s) for s in r['shape']]):
        v = read_value(data, r['offset'], r['shape'], scoords)
        tcoords = [0] * len(r['shape'])
        for k, ax in enumerate(order):
            tcoords[k] = scoords[ax]
        struct.pack_into('<i', buf, lin(tuple(tcoords), tshape) * ITEM, v)
    return bytes(buf)

data = bytearray(128)
a = {'name': 'A', 'offset': 8, 'shape': (2, 3), 'order': (1, 0)}
b = {'name': 'B', 'alias_of': 'A', 'shape': (2, 3), 'order': (1, 0)}
c = {'name': 'C', 'offset': 40, 'shape': (4,), 'order': (0,)}
records = [a, b, c]
write_tensor(data, 8, (2, 3), 0)
write_tensor(data, 40, (4,), 100)

validate(records, len(data), {'A', 'C'})
mat = materialize(records, data)
layout_ok = mat['A'] == reference(records, data, 'A')
alias_ok = mat['B'] == mat['A']
identity_ok = mat['C'] == bytes(data[40:40 + 4 * ITEM])
print('layout transpose ok:', layout_ok)
print('alias bytes ok:', alias_ok)
print('identity slice ok:', identity_ok)

unique_bytes = sum(prod(r['shape']) * ITEM for r in records if 'alias_of' not in r)
naive_bytes = sum(prod(r['shape']) * ITEM for r in records)
print('alias capacity bytes (unique, naive):', unique_bytes, naive_bytes)

bad_overlap = [
    {'name': 'X', 'offset': 8, 'shape': (2, 3), 'order': (1, 0)},
    {'name': 'Y', 'offset': 16, 'shape': (4,), 'order': (0,)}
]
try:
    validate(bad_overlap, len(data), {'X', 'Y'})
    overlap_rejected = False
except LoadError:
    overlap_rejected = True
print('overlap rejected:', overlap_rejected)

declared = [{'name': 'T', 'offset': 8, 'shape': (2, 3), 'order': (1, 0)}]
expected_t = reference(declared, data, 'T')
buggy_t = materialize(declared, data, ignore_order=True)['T']
transpose_detected = buggy_t != expected_t
print('ignored transpose detected:', transpose_detected)

def pipeline(fail_at=None, early_publish=False, early_release=False):
    errors = []
    published = False
    publish_at = -1
    pending = set()
    for i in range(2):
        buf = 'b' + str(i % 2)
        if early_release and i > 0:
            old = 'b' + str((i - 1) % 2)
            if old in pending:
                errors.append('buffer reused while pending')
        if early_publish and i == 0:
            published = True
            publish_at = 0
        if fail_at == i:
            break
        pending.add(buf)
    if fail_at is None and not early_publish:
        pending.clear()
        published = True
        publish_at = 2
    if published and publish_at < 2:
        errors.append('published before all chunks drained')
    return published, errors, publish_at

ok_pub, ok_err, ok_at = pipeline(fail_at=1)
bad_pub, bad_err, bad_at = pipeline(fail_at=1, early_publish=True)
rel_pub, rel_err, rel_at = pipeline(fail_at=None, early_release=True)
print('failure pipeline published/errors:', ok_pub, ok_err, ok_at)
print('early publish negative control errors:', bad_err)
print('early release negative control errors:', rel_err)

assert layout_ok
assert alias_ok
assert identity_ok
assert unique_bytes == 40
assert naive_bytes == 64
assert overlap_rejected
assert transpose_detected
assert ok_pub is False and ok_err == []
assert bad_err != []
assert rel_err != []
print('PASS: CPU checks and negative controls')
